typography-bar.snippet:
.typography-bar
display: inline-block;
box-sizing: border-box;
font-family: var(--eds-family-sans); /* "EDS Text", "PingFang SC", SourceHanSansSC, "Apple Color Emoji", "Segoe UI Emoji" */
font-size: calc(var(--eds-bar-size) * 2);
font-weight: var(--eds-bar-weight); /* 500 */
line-height: calc(var(--eds-bar-line-height) * 2);
transform: scale(0.5);
transform-origin: top center;
margin-bottom: calc(var(--eds-bar-line-height) * -1);
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;

motion-layout.snippet:
.motion-layout
transition: var(--motion-recipe-enter);
opacity: var(--motion-opacity-hidden);
transform: translateY(var(--motion-distance-sm));

motion-flotation.snippet:
.motion-flotation
transition: var(--motion-recipe-flotation-enter);
opacity: var(--motion-opacity-hidden);
transform: translateY(var(--motion-offset-flotation-y)) scale(var(--motion-scale-present));
